def calculate_next(xi, x_minus_1):
    # Recurrence: x_{i+1} = (x_i^2 - x_{i-1}) / (x_{i-1} + 1)
    # Or, derived from (x_{i+1} + 1)(x_{i-1} + 1) = x_i^2 + 1

    # We use the simplified formula:
    numerator = xi**2 - x_minus_1
    denominator = x_minus_1 + 1

    if denominator == 0:
        return None # Should not happen since x_{i-1} >= 1

    if numerator % denominator != 0:
        return None # Not an integer

    x_next = numerator // denominator

    if x_next <= 0:
        return None # Not a positive integer

    return x_next

def generate_sequence(x1, x2, max_len=100):
    sequence = [x1, x2]

    if x1 <= 0 or x2 <= 0:
        return sequence # Invalid starting sequence

    xi_minus_1 = x1
    xi = x2

    for i in range(2, max_len):
        x_next = calculate_next(xi, xi_minus_1)

        if x_next is None:
            break

        sequence.append(x_next)

        # Update for next iteration
        xi_minus_1 = xi
        xi = x_next

    return sequence

